import type { EngineState, RuntimeResourceState } from "./types.js";

/**
 * Only own canonical IDs are resources. Untrusted, externally reconstructed
 * EngineState maps may have the default JavaScript Object prototype rather
 * than the null-prototype dictionary generated by Engine itself. Never
 * interpret inherited entries such as "constructor", "toString" or
 * "__proto__" as an actual network or identity endpoint.
 */
export function ownResource(state: EngineState, id: string): RuntimeResourceState | undefined {
  return typeof id === "string" &&
    Object.prototype.hasOwnProperty.call(state.resources, id)
    ? state.resources[id] : undefined;
}
